-- Cover foreign keys used by deletes, joins and row-level security lookups.
create index if not exists areas_parent_org_idx on public.areas (parent_id, organization_id);
create index if not exists customers_created_by_idx on public.customers (created_by);
create index if not exists inventory_categories_parent_org_idx on public.inventory_categories (parent_id, organization_id);
create index if not exists inventory_costs_updated_by_idx on public.inventory_item_costs (updated_by);
create index if not exists inventory_costs_variant_org_idx on public.inventory_item_costs (variant_id, organization_id);
create index if not exists inventory_items_area_org_idx on public.inventory_items (area_id, organization_id);
create index if not exists inventory_items_category_org_idx on public.inventory_items (category_id, organization_id);
create index if not exists inventory_items_created_by_idx on public.inventory_items (created_by);
create index if not exists inventory_movements_branch_org_idx on public.inventory_movements (branch_id, organization_id);
create index if not exists inventory_movements_created_by_idx on public.inventory_movements (created_by);
create index if not exists inventory_movements_variant_org_idx on public.inventory_movements (variant_id, organization_id);
create index if not exists inventory_stock_branch_org_idx on public.inventory_stock (branch_id, organization_id);
create index if not exists inventory_stock_variant_org_idx on public.inventory_stock (variant_id, organization_id);
create index if not exists inventory_variants_item_org_idx on public.inventory_variants (item_id, organization_id);
create index if not exists memberships_branch_org_idx on public.organization_memberships (branch_id, organization_id);
create index if not exists memberships_user_idx on public.organization_memberships (user_id);
create index if not exists public_requests_assigned_to_idx on public.public_requests (assigned_to);
create index if not exists public_requests_created_by_idx on public.public_requests (created_by);
create index if not exists sale_lines_organization_idx on public.sale_lines (organization_id);
create index if not exists sale_lines_sale_org_idx on public.sale_lines (sale_id, organization_id);
create index if not exists sale_lines_variant_org_idx on public.sale_lines (variant_id, organization_id);
create index if not exists sales_branch_org_idx on public.sales (branch_id, organization_id);
create index if not exists sales_created_by_idx on public.sales (created_by);
create index if not exists sales_customer_org_idx on public.sales (customer_id, organization_id);
create index if not exists sales_organization_idx on public.sales (organization_id);
create index if not exists transfer_lines_organization_idx on public.stock_transfer_lines (organization_id);
create index if not exists transfer_lines_transfer_org_idx on public.stock_transfer_lines (transfer_id, organization_id);
create index if not exists transfer_lines_variant_org_idx on public.stock_transfer_lines (variant_id, organization_id);
create index if not exists transfers_approved_by_idx on public.stock_transfers (approved_by);
create index if not exists transfers_dispatched_by_idx on public.stock_transfers (dispatched_by);
create index if not exists transfers_from_branch_org_idx on public.stock_transfers (from_branch_id, organization_id);
create index if not exists transfers_received_by_idx on public.stock_transfers (received_by);
create index if not exists transfers_requested_by_idx on public.stock_transfers (requested_by);
create index if not exists transfers_to_branch_org_idx on public.stock_transfers (to_branch_id, organization_id);

-- Split broad FOR ALL policies so read checks do not run twice per query.
drop policy branches_manage on public.branches;
create policy branches_add on public.branches for insert to authenticated with check (app_private.has_org_role(organization_id, id, array['owner','admin','manager']));
create policy branches_update on public.branches for update to authenticated using (app_private.has_org_role(organization_id, id, array['owner','admin','manager'])) with check (app_private.has_org_role(organization_id, id, array['owner','admin','manager']));
drop policy areas_manage on public.areas;
create policy areas_add on public.areas for insert to authenticated with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager']));
create policy areas_update on public.areas for update to authenticated using (app_private.has_org_role(organization_id, null, array['owner','admin','manager'])) with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager']));
drop policy categories_manage on public.inventory_categories;
create policy categories_add on public.inventory_categories for insert to authenticated with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse']));
create policy categories_update on public.inventory_categories for update to authenticated using (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse'])) with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse']));
drop policy items_manage on public.inventory_items;
create policy items_add on public.inventory_items for insert to authenticated with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production']));
create policy items_update on public.inventory_items for update to authenticated using (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production'])) with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production']));
drop policy variants_manage on public.inventory_variants;
create policy variants_add on public.inventory_variants for insert to authenticated with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production']));
create policy variants_update on public.inventory_variants for update to authenticated using (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production'])) with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','production']));
drop policy transfer_lines_manage on public.stock_transfer_lines;
create policy transfer_lines_add on public.stock_transfer_lines for insert to authenticated with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse','advisor']));
create policy transfer_lines_update on public.stock_transfer_lines for update to authenticated using (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse'])) with check (app_private.has_org_role(organization_id, null, array['owner','admin','manager','warehouse']));
